const body = $json.body || {}
const headers = $json.headers || {}

const suppliedToken = String(headers['x-govchat-token'] || headers['X-Govchat-Token'] || '').trim()
const expectedToken = String($env.N8N_WEBHOOK_TOKEN || '').trim()

if (!expectedToken) throw new Error('Server misconfiguratie: N8N_WEBHOOK_TOKEN ontbreekt')
if (!suppliedToken || suppliedToken !== expectedToken) throw new Error('Unauthorized webhook token')

const sourceText = String(body.text || body.transcript || '').replace(/[\r\n\t]+/g, ' ').replace(/\s+/g, ' ').trim()
if (!sourceText) throw new Error('Veld "text" is verplicht')

const language = String(body.language || 'nl').trim() || 'nl'
const maxChars = Math.max(32, Math.min(140, Number(body.max_chars) || 72))
const model = String(body.model || $env.LITELLM_TITLE_MODEL || 'gpt-4o-mini').trim() || 'gpt-4o-mini'

const clipped = sourceText.slice(0, 4000)

const system = `Je maakt een korte, duidelijke titel voor een transcriptie-sessie.\nRegels:\n- Gebruik dezelfde taal als de gebruiker (taalcode: ${language}).\n- Maximaal ${maxChars} tekens.\n- Geen aanhalingstekens.\n- Geen punt op het einde.\n- Lever exact één titelregel, zonder extra uitleg.`

const user = `Transcriptie:\n${clipped}`

return [{
  json: {
    model,
    maxChars,
    requestBody: {
      model,
      temperature: 0.2,
      max_tokens: 48,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
    },
  },
}]

const response = $json || {}
const text = String(response?.choices?.[0]?.message?.content || response?.output_text || response?.text || '').replace(/[\r\n\t]+/g, ' ').replace(/\s+/g, ' ').replace(/^\s*["'`]+|["'`]+\s*$/g, '').trim()
const maxChars = Math.max(32, Math.min(140, Number($item(0).$node['Prepare Title Request'].json.maxChars) || 72))
const title = (text.length > maxChars ? text.slice(0, maxChars).trim() : text) || 'Transcriptie sessie'
return [{ json: { title } }]
